double sign = ((row + col) % 2 == 0) ? 1.0 : -1.0;
int i = 0;
double sub[2][2];
for (int r = 0; r < 3; ++r) {
    if (r == row) continue;
    int j = 0;
    for (int c = 0; c < 3; ++c) {
        if (c == col) continue;
        sub[i][j] = m[r][c];
        ++j;
    }
    ++i;
}
double det = sub[0][0] * sub[1][1] - sub[0][1] * sub[1][0];
return sign * det;

